(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["microbiology-exam-3"]={"title":"Microbiology Exam 3","sections":[{"id":"l14-scope","title":"L14 · What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-endotoxin-sorting","title":"L14 · Endotoxin & Sorting","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-pseudomonas","title":"L14 · Pseudomonas & Its Relatives","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-zoonoses-human","title":"L14 · Brucella, Francisella, Bordetella, Legionella","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-enterics","title":"L14 · The Enterics: Traits, Media, Antigens","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-ecoli","title":"L14 · Escherichia coli Pathotypes","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-coliforms-proteus","title":"L14 · Other Coliforms & Proteus","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-salmonella-shigella","title":"L14 · Salmonella, Shigella, Enteric Yersinia","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-plague","title":"L14 · Yersinia pestis & Plague","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-pasteurella-haemophilus","title":"L14 · Pasteurella & Haemophilus","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-transmission","title":"L14 · Objective 2: How We Get Them","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"}],"rows":[{"t":"★ The four E. coli strains","d":"“There are four different strains of E. coli that you need to know. Hint, hint, hint, hint.” ENTEROTOXIGENIC (traveler's diarrhea) · ENTEROINVASIVE (no toxins, shigellosis-like) · ENTEROPATHOGENIC (infant wasting diarrhea, microvilli) · ENTEROHEMORRHAGIC O157:H7 (Shiga toxin, hemolytic uremic syndrome).","s":0},{"t":"★ Cystic fibrosis","d":"Pseudomonas aeruginosa: “very, very, very common with cystic fibrosis patients” (the slide's own star). Burkholderia cepacia with it = 80% fatality.","s":0},{"t":"★ Endotoxin","d":"“Any gram-negative organism will have that weapon.” Lipid A; released on lysis, so killing them with antibiotics can make the patient feel worse first.","s":0},{"t":"No drug questions","d":"“I'm not going to be testing on which antibiotics.” Non-drug management (fluids, dialysis, plasmapheresis, vaccines, breast feeding, quarantine) is fair game.","s":0},{"t":"Not to memorize","d":"Slide 8's endotoxin diagram · slide 19's body map of Pseudomonas infections (“it can hit you pretty much anywhere”) · percentages · slide 47's biochemical tree.","s":0},{"t":"Association only","d":"Proteus and bladder/kidney stones: “association, not causation.”","s":0},{"t":"Where the time went","d":"E. coli ~17 min · Pseudomonas 14 · plague 12 · endotoxin 10 · enterics 9 · Salmonella 9 · pertussis 8 · Legionella 8 (mostly outbreaks). One transcript only; she corrected no slide.","s":0},{"t":"Endotoxin","d":"LIPOPOLYSACCHARIDE of the outer membrane. LIPID A = biologically active part. Released on LYSIS (including by antibiotics) and during rapid growth.","s":1},{"t":"Three parts","d":"Lipid A (active) · core polysaccharide (same for large groups) · O antigen (unique per organism; repeat number = rough, semi-rough, smooth).","s":1},{"t":"Usually protective","d":"Innate immunity via a lipopolysaccharide binding complex + Toll-like receptor → moderated inflammation keeps mucosal infection mucosal.","s":1},{"t":"Damaging","d":"Complement (hemorrhagic necrosis) · coagulation (disseminated intravascular coagulation, bradykinin) · high levels impair neutrophil CHEMOTAXIS · macrophages release tumor necrosis factor, interleukins 1 and 6.","s":1},{"t":"Low vs flood","d":"Low: fever, malaise, aches. Flood: SEPTIC SHOCK — microthrombi, vasodilation, cardiac output first UP (warm shock), then down → organ failure.","s":1},{"t":"Three sorting properties","d":"OXYGEN requirement · LACTOSE fermentation · OXIDASE enzyme.","s":1},{"t":"Aerobes, no fermentation","d":"Pseudomonas, Burkholderia, Bordetella, Francisella, Brucella, Alcaligenes. Pairs: Pseudomonas + Burkholderia OPPORTUNISTS · Brucella + Francisella ZOONOTIC · Bordetella + Legionella HUMAN.","s":1},{"t":"Facultative anaerobes","d":"Lactose + (coliforms): Escherichia, Klebsiella, Citrobacter, Enterobacter. Lactose −, oxidase −: Salmonella, Shigella, Proteus, Yersinia and others. Lactose −, OXIDASE +: Haemophilus, Pasteurella. Obligate anaerobe: Bacteroides.","s":1},{"t":"Pseudomonads","d":"Small rods, ONE POLAR flagellum · aerobic, NO fermentation · oxidase + catalase + · water-soluble pigments · soil and water.","s":2},{"t":"P. aeruginosa signs","d":"GRAPELIKE odor · greenish-blue pigment PYOCYANIN · resists soaps, quaternary ammonium disinfectants, drying.","s":2},{"t":"Why hospitals","d":"BIOFILMS → contaminates ventilators, intravenous solutions, anesthesia equipment. Major nosocomial agent.","s":2},{"t":"Virulence","d":"Exotoxin A blocks PROTEIN SYNTHESIS · slime layer (anti-phagocytosis, biofilm) · exoenzyme S → T cell APOPTOSIS · multidrug resistant (permeability, enzymes, efflux pumps, gene transfer).","s":2},{"t":"Disease","d":"★ Burns, neoplastic disease, CYSTIC FIBROSIS. Septicemia → endocarditis, meningitis. Healthy people: rash, urinary tract infection, SWIMMER'S EAR, CORNEAL ULCER (contact lenses).","s":2},{"t":"Vaccine","d":"In development, for cystic fibrosis; but in CHRONIC cystic fibrosis infection it may worsen lung inflammation.","s":2},{"t":"Relatives","d":"Obligate aerobes, no sugar fermentation, opportunists. B. cepacia: cystic fibrosis copathogen, mutates fast. B. pseudomallei: MELIOIDOSIS, tropical soil, injury or inhalation. A. baumannii: MONTHS on fomites, combat wounds. S. maltophilia: biofilms on equipment.","s":2},{"t":"Brucella","d":"Tiny coccobacilli. B. abortus (CATTLE), B. suis (PIGS). Malta / UNDULANT / Bang fever: fever fluctuating weeks to a year. Slaughtering, placentas, UNPASTEURIZED dairy. Agglutination titer. ANIMAL vaccine.","s":3},{"t":"Francisella tularensis","d":"TULAREMIA, rabbit fever. Animals, water and dust, vector bites; 10–50 organisms. Ulcerative skin lesion + swollen nodes. Intracellular → RELAPSE. Attenuated vaccine.","s":3},{"t":"Bordetella pertussis","d":"Minute encapsulated coccobacillus. Healthy CARRIERS; contact or aerosols. Binds and destroys CILIATED cells → mucus blocks airways.","s":3},{"t":"Pertussis stages","d":"CATARRHAL (drainage, sneezing, occasional cough) → PAROXYSMAL (persistent cough + the WHOOP).","s":3},{"t":"Pertussis prevention","d":"DTaP (diphtheria, tetanus and acellular pertussis): ACELLULAR, toxoid + antigens, 5 doses 2 months–6 years. Rising: infants under 2 months unvaccinable · WANING immunity · pertactin-negative strains.","s":3},{"t":"Legionella","d":"WEAKLY Gram negative, pleomorphic. Hard to culture: CHARCOAL YEAST EXTRACT agar. Lives with AMEBAS in water. AEROSOLS (cooling towers, fountains). Legionnaires disease, Pontiac fever. Men over 50, smokers, nosocomial elderly.","s":3},{"t":"Family traits","d":"Small non-spore-forming rods · FACULTATIVE anaerobes · ALL ferment GLUCOSE · nitrate → nitrite · OXIDASE − · catalase + · all have O antigen.","s":4},{"t":"Coliform vs not","d":"COLIFORMS ferment LACTOSE; non-coliforms do not.","s":4},{"t":"Two kinds of diarrhea","d":"TOXIGENIC: on the surface, oversecretion of fluid (enterotoxigenic E. coli). INVASIVE: enter the lining, bleeding (Shigella).","s":4},{"t":"Media","d":"EMB (eosin methylene blue) and MacConkey's (crystal violet + BILE SALTS): both SELECTIVE for Gram negatives, DIFFERENTIAL for lactose fermenters (pink on MacConkey's).","s":4},{"t":"Antigens","d":"H = FLAGELLAR · K = CAPSULE/fimbrial (Vi in Salmonella) · O = SOMATIC cell wall, all have it.","s":4},{"t":"Hospitals","d":"With Pseudomonas, almost HALF of nosocomial infections; soap dishes, sinks, catheters, tracheal cannulas.","s":4},{"t":"E. coli","d":"Common AEROBIC gut bacterium, but NOT the most prevalent (anaerobic Bacteroides, Bifidobacterium are). Virulence by PLASMID transfer.","s":5},{"t":"Enterotoxigenic","d":"Heat-labile + heat-stable TOXINS → fluid secretion; fimbriae, SMALL intestine. TRAVELER'S DIARRHEA. Fluids; bismuth salicylate counters the toxin.","s":5},{"t":"Enteroinvasive","d":"NO toxins, mechanical damage; LARGE intestine, like SHIGELLOSIS. Bloody diarrhea, high fever.","s":5},{"t":"Enteropathogenic","d":"Adheres and destroys MICROVILLI. Wasting INFANTILE diarrhea, top infant killer worldwide. Prevention: BREAST FEEDING.","s":5},{"t":"Enterohemorrhagic O157:H7","d":"SHIGA toxin binds RIBOSOMES. CATTLE reservoir: beef, water, vegetables; ~100 cells. Hemorrhagic colitis, HEMOLYTIC UREMIC SYNDROME. RAINBOW agar: BLACK colonies (glucuronidase −). Antibiotics may WORSEN it; dialysis, plasmapheresis.","s":5},{"t":"Outside the gut","d":"Most URINARY TRACT INFECTIONS (women, catheters) · neonatal meningitis · COLIFORM COUNT = fecal contamination of water.","s":5},{"t":"Klebsiella pneumoniae","d":"Normal RESPIRATORY flora · LARGE CAPSULE · NOSOCOMIAL PNEUMONIA.","s":6},{"t":"Serratia marcescens","d":"RED pigment PRODIGIOSIN · pneumonia in chronic ALCOHOLICS, burns, urinary tract infections.","s":6},{"t":"Enterobacter · Citrobacter","d":"Opportunistic urinary tract, wound and bloodstream infections.","s":6},{"t":"Proteus","d":"HIGHLY MOTILE, peritrichous flagella → SWARMING waves. Urinary tract infection, bladder and KIDNEY STONES, Crohn's disease.","s":6},{"t":"Providencia · Morganella","d":"Providencia: multiple ANIMAL reservoirs, CATHETER urinary infections. Morganella: like Proteus. Both multidrug resistant.","s":6},{"t":"Salmonella typhi","d":"HUMANS the only host · resists BILE and dyes · fecal food or water (“boil it, cook it, peel it, or forget it”) · chronic GALLBLADDER carriers.","s":7},{"t":"Typhoid course","d":"SMALL intestine → invasive → SEPTICEMIA → liver, spleen; ulceration, PERFORATION. Sustained fever 103–104, ROSE SPOTS. Vaccines: oral (4 doses), injected (1).","s":7},{"t":"Animal salmonelloses","d":"Less severe than typhoid but MORE PREVALENT. Ingestion: POULTRY and EGGS, cattle, REPTILES (pet turtles), backyard flocks. S. cholerae-suis = swine.","s":7},{"t":"Shigella","d":"Fecal food → invades LARGE-intestine villi; does NOT perforate or enter the blood. ENDOTOXIN → fever; ENTEROTOXIN → mucosal damage, blood and mucus. Dysentery; under-5s.","s":7},{"t":"Enteric yersinias","d":"Y. enterocolitica: animals, fish, produce, water; ILEUM inflammation MIMICS APPENDICITIS. Y. pseudotuberculosis: MORE lymph node inflammation.","s":7},{"t":"Organism","d":"Tiny rod, BIPOLAR staining, capsule · COAGULASE, endotoxin, murine toxin. ~200 rodent reservoirs; United States cases WEST of the Mississippi.","s":8},{"t":"The flea","d":"Coagulase CLOTS block the flea's esophagus → RAVENOUS, bites again → REGURGITATES bacteria into the bite. 3–50 bacilli.","s":8},{"t":"Sylvatic vs urban","d":"SYLVATIC = wild animals · URBAN = domestic or semidomestic animals · human to human rare.","s":8},{"t":"Three forms","d":"BUBONIC: lymph node necrosis, the BUBO (groin, axilla) · SEPTICEMIC: purpura → gangrene, the BLACK plague · PNEUMONIC: lungs, highly contagious by AEROSOL.","s":8},{"t":"Diagnose fast","d":"Death within 2 days of symptoms. History, symptoms, ASPIRATE THE BUBO. Killed or attenuated vaccine (military, vets, lab). QUARANTINE + rodent control.","s":8},{"t":"Pasteurella multocida","d":"OXIDASE +; zoonotic, normal ANIMAL flora. Animal BITES or SCRATCHES → local abscess → joints, bones, nodes. Veterinarians; septicemia if immunocompromised.","s":9},{"t":"Haemophilus","d":"“Blood loving,” fastidious. CHOCOLATE agar (cooked blood): needs HEMIN, nicotinamide adenine dinucleotide (NAD) or its phosphate.","s":9},{"t":"H. influenzae","d":"MISNAMED (not the flu). MENINGITIS, EPIGLOTTITIS, otitis media, sinusitis, pneumonia. SUBUNIT vaccine Hib (Haemophilus influenzae type b).","s":9},{"t":"Other species","d":"H. aegyptius: PINK EYE, children, fingers and insects · H. ducreyi: CHANCROID, sexually transmitted · H. parainfluenzae, H. aphrophilus: oral flora → ENDOCARDITIS after dental work.","s":9},{"t":"Water, soil, equipment","d":"Pseudomonas (biofilms on ventilators, intravenous lines) · B. pseudomallei (injury, inhalation) · Acinetobacter (fomites) · Stenotrophomonas (biofilms).","s":10},{"t":"Animals","d":"Brucella (slaughter, unpasteurized dairy) · Francisella (rabbits, water, dust, vectors) · O157:H7 (cattle) · animal salmonelloses (poultry, eggs, reptiles) · Pasteurella (bites) · plague (fleas, rodents).","s":10},{"t":"Air","d":"Bordetella (carriers, aerosols) · Legionella (water aerosols) · pneumonic plague (aerosol).","s":10},{"t":"Fecal-oral","d":"E. coli diarrheal strains, Salmonella typhi (humans only), Shigella.","s":10},{"t":"Self and partner","d":"E. coli urinary tract infection (women, catheters) · H. parainfluenzae (own oral flora, dental work) · H. ducreyi (sexual) · H. aegyptius (fingers, insects).","s":10}],"map":{"microbiology-exam-3-gram-negative-bacilli-quiz-version-2":[36,45,48,53,35,32,29,16,12,38,25,61,26,23,49,43,37,49,51,-1,11,56,1,19,46,55,40,38,7,60],"microbiology-exam-3-gram-negative-bacilli-quiz":[35,38,14,37,34,26,53,15,44,28,-1,54,48,16,26,20,2,45,35,53,41,57,36,10,27,20,47,49,36,21]}};
